const util = require('@node-red/util')
// const nodes = require('@node-red/runtime')

module.exports = {
    generateSuggestion: function(_runtime, node, flow) {
        const suggestion = []
        if (node.type === "http in") {
            console.log(node)
            // add a suggestion for a http response node
            const x = node.x ? node.x + 250 : 250
            const y = node.y ? node.y : 30
            console.log("Adding http response node at:", x, y)
            console.log('type', _runtime.nodes.getType("http response"))
            const httpResponse = {
                id: util.util.generateId(),
                "type": "http response",
                name: "http response",
                statusCode: "",
                headers: {},
                "x": x,
                "y": y,
                "z": node.z,
                "wires": []
            };
            console.log("Adding http response node:", httpResponse)
            suggestion.push(httpResponse)
            
            // {
            //     "id": util.util.generateId(),
            //     "type": "http response",
            //     "z": node.z,
            //     "name": "",
            //     "statusCode": "",
            //     "headers": {},
            //     "x": x,
            //     "y": y,
            //     "wires": []
            // }
        }
        return {
            suggestions: [
                suggestion
            ]
        }
    }
}